head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[layer > M > hideModal]<br/>showModal() 메소드로 표시한 모달 레이어를 숨기고, 비활성화(disabled) 되었던 컴포넌트를 원래 상태로 복원합니다.",
    "validation" : [
        "hideModal() 호출 시 모달 레이어가 숨겨져야 합니다.",
        "hideModal() 호출 시 비활성화되었던 컴포넌트가 원래 상태로 복원되어야 합니다.",
        "showModal() 로 차단되었던 Tab 키에 의한 포커스 이동도 함께 해제되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_showModal_onclick = function () {
    // hideModal 테스트를 위해 btn_hideModal 만 활성 유지한 상태로 모달 표시
    WebSquare.layer.showModal(["btn_hideModal", "wf_body_bottom"]);
    wf_body_bottom.getObj("scwin").setReturnValue("showModal() 호출 → 모달 표시됨");
    wf_body_bottom.getObj("scwin").setReturnValue("input_test, btn_disabled_test 비활성화 확인");
}



scwin.btn_hideModal_onclick = function () {
    WebSquare.layer.hideModal();

    setTimeout(function () {
        var result = [];

        // 모달 레이어 숨김 확인 (DOM 제거 또는 display:none)
        var modalOverlay = document.querySelector(".w2modal");
        var isHidden = !modalOverlay || modalOverlay.style.display === "none" || getComputedStyle(modalOverlay).display === "none";
        result.push("모달 레이어 숨김 : " + (isHidden ? "PASS" : "FAIL"));

        // 컴포넌트 복원 확인 - input 활성화 여부
        var inputEl = document.querySelector("[id*='input_test']");
        if (inputEl) {
            var isDisabled = inputEl.getAttribute("disabled") === "true" || inputEl.classList.contains("w2input_disabled");
            result.push("input_test 복원 (disabled 해제) : " + (!isDisabled ? "PASS" : "FAIL"));
        }

        // 버튼 클릭 가능 확인
        result.push("btn_disabled_test 클릭하여 복원 확인 가능");

        wf_body_bottom.getObj("scwin").setReturnValue(result.join("\n"));
    }, 500);
}



scwin.btn_disabled_test_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("btn_disabled_test 클릭됨 → 컴포넌트 복원 확인 PASS");
}
